using NUnit.Framework;

[TestFixture]
public class CountCategoriesTests
{
    [Test]
    public void Counts_All_Categories()
    {
        var result = CountCategories("Anna 123!");
        Assert.That(result.letters, Is.EqualTo(4));
        Assert.That(result.digits, Is.EqualTo(3));
        Assert.That(result.spaces, Is.EqualTo(1));
        Assert.That(result.special, Is.EqualTo(1));
    }

    private (int letters, int digits, int spaces, int special) CountCategories(string text)
    {
        int letters = 0, digits = 0, spaces = 0, special = 0;

        foreach (var ch in text)
        {
            if (char.IsLetter(ch))
                letters++;
            else if (char.IsDigit(ch))
                digits++;
            else if (char.IsWhiteSpace(ch))
                spaces++;
            else
                special++;
        }

        return (letters, digits, spaces, special);
    }
}
